VALUES ('club_lexington-just-games-lexington', 'Just Games Lexington', 'lexington-just-games-lexington', 'Official event page lists recurring Mahjong Meet Ups in Lexington with staff instruction for players who do not know how to play. The page does not identify the variant as American/NMJL, so retained for review.', (SELECT id FROM City WHERE name = 'Lexington' AND state = 'KY'), 'Lexington, KY', 'https://justgameslex.com/', NULL, NULL, NULL, NULL, 1, 1, 1, 1, 0, 0, 10, 'Tuesday and Saturday afternoons; multiple October and November 2026 dates listed.', 'https://justgameslex.com/event/mahjong/?occurrence=2026-10-10', '2026-09-30', 'NEEDS_REVIEW')
